 if(n.snippets){const s=n.snippets;if(!Array.isArray(s.entries)||s.entries.length>150||s.selected!==null&&!id(s.selected))throw Error('Invalid snippet shelf');const ids=new Set();for(const e of s.entries){if(!id(e.id)||ids.has(e.id)||!text(e.title,160)||!text(e.tags,300)||!text(e.text,20000))throw Error('Invalid snippet');ids.add(e.id);}if(s.selected!==null&&!ids.has(s.selected))throw Error('Invalid selected snippet');}
 if(n.streak){const b=n.streak;if(!Array.isArray(b.habits)||b.habits.length>30||b.selected!==null&&!id(b.selected))throw Error('Invalid streak board');const ids=new Set();for(const h of b.habits){if(!id(h.id)||ids.has(h.id)||!text(h.name,120)||!text(h.unit,30)||!Number.isFinite(h.goal)||h.goal<=0||h.goal>1e6||!Number.isFinite(h.dailyTarget)||h.dailyTarget<=0||h.dailyTarget>1e6||!h.logs||typeof h.logs!=='object'||Array.isArray(h.logs)||Object.keys(h.logs).length>3660||Object.entries(h.logs).some(([d,v])=>!validDate(d)||!Number.isFinite(v)||v<0||v>1e6))throw Error('Invalid habit');ids.add(h.id);}if(b.selected!==null&&!ids.has(b.selected))throw Error('Invalid habit selection');}
 if(n.flash){const d=n.flash;if(!Array.isArray(d.cards)||d.cards.length>500||d.selected!==null&&!id(d.selected))throw Error('Invalid flash cards');const ids=new Set();for(const c of d.cards){if(!id(c.id)||ids.has(c.id)||!text(c.front,6000)||!text(c.back,12000)||!text(c.tags,300)||typeof c.known!=='boolean'||!Number.isSafeInteger(c.reviews)||c.reviews<0||!Number.isFinite(c.lastReview)||c.lastReview<0)throw Error('Invalid flash card');ids.add(c.id);}if(d.selected!==null&&!ids.has(d.selected))throw Error('Invalid selected flash card');const s=d.study;if(s!==null&&(!s||typeof s.active!=='boolean'||typeof s.flipped!=='boolean'||!Array.isArray(s.order)||s.order.length>500||new Set(s.order).size!==s.order.length||s.order.some(i=>!ids.has(i))||!Number.isInteger(s.cursor)||s.cursor<0||s.cursor>s.order.length||s.active&&s.cursor>=s.order.length))throw Error('Invalid study session');}
 if(n.scanner){const s=n.scanner;if(!Array.isArray(s.pages)||s.pages.length>20||!Number.isInteger(s.pdfPages)||s.pdfPages<0||s.pdfPages>20||!text(s.notes,100000)||s.dirty!==undefined&&typeof s.dirty!=='boolean')throw Error('Invalid scan');const ids=new Set();for(const p of s.pages){if(!id(p.id)||ids.has(p.id)||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.data)||p.data.length>4e6||![0,90,180,270].includes(p.rotation)||!['original','gray','clean'].includes(p.filter)||!Number.isFinite(p.margin)||p.margin<0||p.margin>30)throw Error('Invalid scan page');ids.add(p.id);}if(n.data&&(!/^data:application\/pdf;base64,[A-Za-z0-9+/=]+$/.test(n.data)||n.data.length>17e6))throw Error('Invalid scan PDF');}
